static float tm_buf[3][4096];

static inline void tm_conv(const float *x, int tin, int cin, float *y, int tout, int cout, int k, int s, int pl,
                    const float *w, const float *b, int relu) {
  for (int t = 0; t < tout; t++)
    for (int o = 0; o < cout; o++) {
      float acc = b[o];
      for (int j = 0; j < k; j++) {
        int ti = t * s + j - pl;
        if (ti < 0 || ti >= tin) continue;
        const float *xi = x + ti * cin; const float *wj = w + (j * cin) * cout + o;
        for (int c = 0; c < cin; c++) acc += xi[c] * wj[c * cout];
      }
      y[t * cout + o] = relu && acc < 0 ? 0 : acc;
    }
}
static inline void tm_dw(const float *x, int tin, int c, float *y, int tout, int k, int s, int pl,
                  const float *w, const float *b, int relu) {
  for (int t = 0; t < tout; t++)
    for (int ch = 0; ch < c; ch++) {
      float acc = b[ch];
      for (int j = 0; j < k; j++) {
        int ti = t * s + j - pl;
        if (ti >= 0 && ti < tin) acc += x[ti * c + ch] * w[j * c + ch];
      }
      y[t * c + ch] = relu && acc < 0 ? 0 : acc;
    }
}
static inline void tinymotion_normalise(const float raw[TINYMOTION_WINDOW][TINYMOTION_CHANNELS], float out[TINYMOTION_WINDOW][TINYMOTION_CHANNELS]) {
  for (int t = 0; t < TINYMOTION_WINDOW; t++)
    for (int c = 0; c < TINYMOTION_CHANNELS; c++) out[t][c] = (raw[t][c] - tinymotion_mean[c]) / tinymotion_std[c];
}
/* Returns the index of the most likely class; writes logits to out. */
static inline int tinymotion_predict(const float x[TINYMOTION_WINDOW][TINYMOTION_CHANNELS], float out[TINYMOTION_CLASSES]) {
  const float *x0 = &x[0][0];
  tm_conv(x0, 128, 9, tm_buf[0], 128, 32, 5, 1, 2, tinymotion_w + 0, tinymotion_w + 1440, 1);
  tm_dw(tm_buf[0], 128, 32, tm_buf[1], 128, 7, 1, 3, tinymotion_w + 1472, tinymotion_w + 1696, 1);
  tm_conv(tm_buf[1], 128, 32, tm_buf[2], 128, 32, 1, 1, 0, tinymotion_w + 1728, tinymotion_w + 2752, 0);
  for (int i = 0; i < 4096; i++) { float v = tm_buf[0][i] + tm_buf[2][i]; tm_buf[1][i] = 1 && v < 0 ? 0 : v; }
  tm_dw(tm_buf[1], 128, 32, tm_buf[0], 64, 7, 2, 2, tinymotion_w + 2784, tinymotion_w + 3008, 1);
  tm_conv(tm_buf[0], 64, 32, tm_buf[1], 64, 48, 1, 1, 0, tinymotion_w + 3040, tinymotion_w + 4576, 1);
  tm_dw(tm_buf[1], 64, 48, tm_buf[0], 64, 7, 1, 3, tinymotion_w + 4624, tinymotion_w + 4960, 1);
  tm_conv(tm_buf[0], 64, 48, tm_buf[2], 64, 48, 1, 1, 0, tinymotion_w + 5008, tinymotion_w + 7312, 0);
  for (int i = 0; i < 3072; i++) { float v = tm_buf[1][i] + tm_buf[2][i]; tm_buf[0][i] = 1 && v < 0 ? 0 : v; }
  tm_dw(tm_buf[0], 64, 48, tm_buf[1], 32, 7, 2, 2, tinymotion_w + 7360, tinymotion_w + 7696, 1);
  tm_conv(tm_buf[1], 32, 48, tm_buf[0], 32, 64, 1, 1, 0, tinymotion_w + 7744, tinymotion_w + 10816, 1);
  tm_dw(tm_buf[0], 32, 64, tm_buf[1], 32, 7, 1, 3, tinymotion_w + 10880, tinymotion_w + 11328, 1);
  tm_conv(tm_buf[1], 32, 64, tm_buf[2], 32, 64, 1, 1, 0, tinymotion_w + 11392, tinymotion_w + 15488, 0);
  for (int i = 0; i < 2048; i++) { float v = tm_buf[0][i] + tm_buf[2][i]; tm_buf[1][i] = 1 && v < 0 ? 0 : v; }
  tm_dw(tm_buf[1], 32, 64, tm_buf[0], 16, 7, 2, 2, tinymotion_w + 15552, tinymotion_w + 16000, 1);
  tm_conv(tm_buf[0], 16, 64, tm_buf[1], 16, 96, 1, 1, 0, tinymotion_w + 16064, tinymotion_w + 22208, 1);
  tm_dw(tm_buf[1], 16, 96, tm_buf[0], 16, 7, 1, 3, tinymotion_w + 22304, tinymotion_w + 22976, 1);
  tm_conv(tm_buf[0], 16, 96, tm_buf[2], 16, 96, 1, 1, 0, tinymotion_w + 23072, tinymotion_w + 32288, 0);
  for (int i = 0; i < 1536; i++) { float v = tm_buf[1][i] + tm_buf[2][i]; tm_buf[0][i] = 1 && v < 0 ? 0 : v; }
  for (int c = 0; c < 96; c++) { float s = 0; for (int t = 0; t < 16; t++) s += tm_buf[0][t * 96 + c]; tm_buf[1][c] = s / 16; }
  for (int o = 0; o < 6; o++) { float s = (tinymotion_w + 32960)[o]; for (int c = 0; c < 96; c++) s += tm_buf[1][c] * (tinymotion_w + 32384)[c * 6 + o]; tm_buf[0][o] = s; }
  int best = 0;
  for (int i = 0; i < TINYMOTION_CLASSES; i++) { out[i] = tm_buf[0][i]; if (out[i] > out[best]) best = i; }
  return best;
}
